type TranslationParams = Record<string, string | number>;
type I18nValue = {
  locale: Locale;
  direction: 'ltr' | 'rtl';
  setLocale: (locale: Locale) => void;
  t: (key: string, params?: TranslationParams) => string;
};

const I18nContext = createContext<I18nValue | null>(null);

export function isLocale(value: string | null | undefined): value is Locale {
  return value === 'fr' || value === 'en' || value === 'ar';
}

function initialLocale(): Locale {
  if (typeof window !== 'undefined') {
    const stored = window.localStorage.getItem('telc-locale');
    if (isLocale(stored)) return stored;
    const browser = window.navigator.language.toLowerCase();
    if (browser.startsWith('ar')) return 'ar';
    if (browser.startsWith('en')) return 'en';
  }
  return 'fr';
}

function interpolate(value: string, params?: TranslationParams) {
  if (!params) return value;
  return value.replace(/\{(\w+)\}/g, (_, key: string) => String(params[key] ?? `{${key}}`));
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(initialLocale);
  const direction = locale === 'ar' ? 'rtl' : 'ltr';

  useEffect(() => {
    document.documentElement.lang = locale;
    document.documentElement.dir = direction;
  }, [direction, locale]);

  const value = useMemo<I18nValue>(() => ({
    locale,
    direction,
    setLocale: (next) => {
      window.localStorage.setItem('telc-locale', next);
      setLocaleState(next);
    },
    t: (key, params) => interpolate(messages[locale][key] ?? messages.fr[key] ?? key, params),
  }), [direction, locale]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const value = useContext(I18nContext);
  if (!value) throw new Error('useI18n must be used inside I18nProvider');
  return value;
}
